// ========================================
// OPTION 1: Direct Zillow Scraping (May get blocked)
// Replace "Mock Zillow Data" node with this code
// ========================================

const webhookData = $('Keep User Details').first().json;
const zillowUrl = webhookData.zillowUrl;

if (!zillowUrl || !zillowUrl.includes('zillow.com')) {
  throw new Error('Invalid Zillow URL provided');
}

// Extract Zillow property ID (zpid) from URL
// Examples:
// https://www.zillow.com/homedetails/123-Main-St/12345678_zpid/
// https://www.zillow.com/homes/12345678_zpid/
let zpid;
const zpidMatch = zillowUrl.match(/(\d{8,})_zpid/);
if (zpidMatch) {
  zpid = zpidMatch[1];
} else {
  throw new Error('Could not extract property ID from Zillow URL');
}

console.log('Extracted ZPID:', zpid);

// Zillow's API endpoint (this is what their website uses)
const apiUrl = `https://www.zillow.com/graphql/?zpid=${zpid}&contactFormRenderParameter=&queryId=73a2c96b09979c9c965c224b2a2501d8&operationName=ForSaleShopperPlatformFullRenderQuery`;

// Make the request
const response = await fetch(apiUrl, {
  method: 'GET',
  headers: {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
    'Accept': 'application/json',
    'Accept-Language': 'en-US,en;q=0.9',
    'Referer': zillowUrl,
    'Origin': 'https://www.zillow.com'
  }
});

if (!response.ok) {
  throw new Error(`Zillow API returned ${response.status}: ${response.statusText}`);
}

const data = await response.json();

// Extract property data from Zillow's GraphQL response
const property = data?.data?.property;

if (!property) {
  throw new Error('Could not find property data in Zillow response');
}

// Parse the data into our format
const propertyData = {
  abbreviatedAddress: property.streetAddress || 'Unknown Address',
  address: {
    city: property.city || '',
    state: property.state || '',
    streetAddress: property.streetAddress || '',
    zipcode: property.zipcode || ''
  },
  price: property.price || property.listPrice || 0,
  bedrooms: property.bedrooms || 0,
  bathrooms: property.bathrooms || 0,
  livingArea: property.livingArea || 0,
  description: property.description || property.resoFacts?.stories || '',
  originalPhotos: []
};

// Extract photos
if (property.photos && Array.isArray(property.photos)) {
  propertyData.originalPhotos = property.photos.slice(0, 5).map(photo => ({
    mixedSources: {
      jpeg: [
        { url: photo.url || photo.mixedSources?.jpeg?.[0]?.url, width: 1536 }
      ]
    }
  }));
}

// Fallback if no photos found
if (propertyData.originalPhotos.length === 0) {
  throw new Error('No photos found for this property');
}

console.log('Successfully scraped property:', propertyData.address.streetAddress);
console.log('Found', propertyData.originalPhotos.length, 'photos');

return propertyData;

const data = $input.item.json;
const webhookData = $('Keep User Details').first().json;

let price = 'N/A';
if (data.price) {
  price = typeof data.price === 'number' ? `$${data.price.toLocaleString()}` : data.price;
}

let fullAddress = 'Unknown Address';
if (data.address) {
  if (typeof data.address === 'string') {
    fullAddress = data.address;
  } else {
    const street = data.address.streetAddress || '';
    const city = data.address.city || '';
    const state = data.address.state || '';
    fullAddress = `${street}, ${city}, ${state}`.trim();
  }
}

const beds = data.bedrooms || 'N/A';
const baths = data.bathrooms || 'N/A';
const sqft = data.livingArea || 'N/A';
let description = data.description || '';

const allImages = [];

if (data.originalPhotos && Array.isArray(data.originalPhotos)) {
  data.originalPhotos.forEach((photo) => {
    if (photo.mixedSources?.jpeg) {
      const jpegSources = photo.mixedSources.jpeg;
      const imageUrl = jpegSources[jpegSources.length - 1]?.url;
      if (imageUrl) {
        allImages.push({ url: imageUrl, caption: '' });
      }
    }
  });
}

const selectedImages = allImages.slice(0, 2);
const imageUrls = selectedImages.map(img => img.url);

if (imageUrls.length === 0) {
  throw new Error('No images found in data!');
}

return {
  price: String(price),
  address: fullAddress,
  beds: String(beds),
  baths: String(baths),
  sqft: String(sqft),
  description: String(description).slice(0, 500),
  images: imageUrls,
  imageCount: imageUrls.length,
  name: webhookData.name,
  email: webhookData.email
};

const response = $input.item.json;
const content = response.choices[0].message.content;
const webhookData = $('Keep User Details').first().json;
const descriptions = content.split('\n').filter(line => line.trim().length > 10).slice(0, 2);
const propertyData = $('Parse Property Data').first().json;

const imageData = propertyData.images.map((imageUrl, index) => ({
  imageUrl,
  description: descriptions[index] || 'Beautiful property feature with smooth cinematic pan, professional lighting',
  index
}));

return imageData.map(item => ({
