const gdriveFileId = $json.id;
const descriptionsNode = $('Generate Descriptions').first().json;
const kiePrompt = descriptionsNode.choices[0].message.content;
const propertyNode = $('Prepare Image Data').first().json;

return {
  gdriveFileId: gdriveFileId,
  // Use thumbnail endpoint for direct image access
  gdrivePublicUrl: `https://drive.google.com/thumbnail?id=${gdriveFileId}&sz=w2000`,
  kiePrompt: kiePrompt,
