  price: propertyNode.price,
  beds: propertyNode.beds,
  baths: propertyNode.baths,
  sqft: propertyNode.sqft,
  name: propertyNode.name,
  email: propertyNode.email
};

const apiResponse = $input.item.json;

if (apiResponse.code !== 200 || !apiResponse.data || !apiResponse.data.taskId) {
  throw new Error(`Kie.ai Task Failed. Code: ${apiResponse.code}, Msg: ${apiResponse.msg}`);
}

// Get data directly from Prepare Image Data (no GDrive needed)
const propertyData = $('Prepare Image Data').first().json;

console.log('=== STORE TASK INFO ===');
console.log('Task ID:', apiResponse.data.taskId);
console.log('Address:', propertyData.address);

return {
  taskId: apiResponse.data.taskId,
  description: propertyData.currentDescription,
  imageUrl: propertyData.currentImage, // Direct Zillow URL
  address: propertyData.address,
  price: propertyData.price,
  beds: propertyData.beds,
  baths: propertyData.baths,
  sqft: propertyData.sqft,
  name: propertyData.name,
  email: propertyData.email,
  retryCount: 0
};

const statusResponse = $input.item.json;
let propertyData = $input.item.json;

// Restore property data if lost
if (!propertyData.address || propertyData.address === 'Address not available') {
  try {
    propertyData = $node['Store Task Info'].json;
  } catch (e) {
    propertyData = $('Store Task Info').first().json;
  }
}

console.log('Status check - Address:', propertyData.address);
console.log('Response code:', statusResponse.code);
console.log('Task state:', statusResponse.data?.state);

// According to API docs:
// - code 200 = success response
// - code 422 = parameter validation failed (ERROR!)
// - state field determines actual task status

// Handle error responses
if (statusResponse.code !== 200) {
  throw new Error(`API Error ${statusResponse.code}: ${statusResponse.msg}`);
}

// Handle missing data
if (!statusResponse.data) {
  throw new Error('No data in API response');
}

// Check task state (from API docs: waiting, success, fail)
const taskState = statusResponse.data.state;

// Task failed
if (taskState === 'fail') {
  const failMsg = statusResponse.data.failMsg || 'Unknown error';
  const failCode = statusResponse.data.failCode || 'N/A';
  throw new Error(`Video generation failed. Code: ${failCode}, Message: ${failMsg}`);
}

// Task completed successfully
if (taskState === 'success') {
  console.log('Status: Complete!');
  return {
    status: 'complete',
    needsRetry: false,
    data: statusResponse.data,
    taskId: propertyData.taskId,
    description: propertyData.description,
    imageUrl: propertyData.imageUrl,
    address: propertyData.address,
    price: propertyData.price,
    beds: propertyData.beds,
    baths: propertyData.baths,
    sqft: propertyData.sqft,
    name: propertyData.name,
    email: propertyData.email
  };
}

// Task still waiting/processing
console.log('Status: Waiting/Processing');
return {
  status: 'waiting',
  needsRetry: true,
  taskId: propertyData.taskId,
  description: propertyData.description,
  imageUrl: propertyData.imageUrl,
  address: propertyData.address,
  price: propertyData.price,
  beds: propertyData.beds,
  baths: propertyData.baths,
  sqft: propertyData.sqft,
  name: propertyData.name,
  email: propertyData.email,
  retryCount: propertyData.retryCount || 0
};

const MAX_RETRIES = 20;
const retryCount = $json.retryCount || 0;

if (retryCount >= MAX_RETRIES) {
  throw new Error(`Timeout after ${MAX_RETRIES} retries (15 minutes)`);
}

return {
  taskId: $json.taskId,
  description: $json.description,
  imageUrl: $json.imageUrl,
  address: $json.address,
  price: $json.price,
  beds: $json.beds,
  baths: $json.baths,
  sqft: $json.sqft,
  name: $json.name,
  email: $json.email,
  retryCount: retryCount + 1,
  status: $json.status
};

const statusData = $input.item.json;

// ByteDance API returns: {resultUrls: [...]}
let resultJson;
if (typeof statusData.data.resultJson === 'string') {
  resultJson = JSON.parse(statusData.data.resultJson);
} else {
  resultJson = statusData.data.resultJson;
}

const videoUrl = resultJson.resultUrls?.[0];

if (!videoUrl) {
  throw new Error('No video URL found in response');
}

const originalData = $node['Store Task Info'].json;

console.log('Video URL:', videoUrl);
console.log('Property:', originalData.address);

return {
